package jobs
import("context";"encoding/json";"time";"matrix-dashboard/core/internal/synapse";"github.com/jackc/pgx/v5/pgxpool";"github.com/rs/zerolog")
type Broadcaster struct{DB *pgxpool.Pool;Synapse *synapse.Client;Logger zerolog.Logger}
func(b *Broadcaster)Run(ctx context.Context){ticker:=time.NewTicker(2*time.Second);defer ticker.Stop();for{select{case<-ctx.Done():return;case<-ticker.C:b.processOne(ctx)}}}
type broadcastJob struct{ID int64;Message string;Throttle int;Retries int;CreatedBy *int64}
func(b *Broadcaster)claim(ctx context.Context)(*broadcastJob,error){tx,err:=b.DB.Begin(ctx);if err!=nil{return nil,err};defer tx.Rollback(ctx);var j broadcastJob;err=tx.QueryRow(ctx,"SELECT id,message,throttle_ms,max_retries,created_by FROM broadcasts WHERE status='queued' OR (status='sending' AND started_at < NOW() - INTERVAL '10 minutes') ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED").Scan(&j.ID,&j.Message,&j.Throttle,&j.Retries,&j.CreatedBy);if err!=nil{return nil,nil};_,err=tx.Exec(ctx,"UPDATE broadcasts SET status='sending',started_at=NOW(),updated_at=NOW() WHERE id=$1",j.ID);if err!=nil{return nil,err};if err=tx.Commit(ctx);err!=nil{return nil,err};return &j,nil}
func(b *Broadcaster)processOne(ctx context.Context){j,err:=b.claim(ctx);if err!=nil{b.Logger.Error().Err(err).Msg("claim broadcast failed");return};if j==nil{return};rows,err:=b.DB.Query(ctx,"SELECT id,user_id,attempts FROM broadcast_recipients WHERE broadcast_id=$1 AND status IN ('pending','retry') ORDER BY id",j.ID);if err!=nil{b.failJob(ctx,j.ID);return};type recipient struct{id int64;user string;attempts int};items:=[]recipient{};for rows.Next(){var x recipient;if rows.Scan(&x.id,&x.user,&x.attempts)==nil{items=append(items,x)}};rows.Close();for _,x:=range items{sent:=false;var event string;var lastErr error;for attempt:=x.attempts;attempt<=j.Retries;attempt++{event,lastErr=b.Synapse.SendServerNotice(ctx,x.user,j.Message);if lastErr==nil{sent=true;_,_=b.DB.Exec(ctx,"UPDATE broadcast_recipients SET status='sent',attempts=$1,event_id=$2,sent_at=NOW(),updated_at=NOW() WHERE id=$3",attempt+1,event,x.id);b.auditRecipient(ctx,j.CreatedBy,"broadcast.recipient.sent",j.ID,x.user,map[string]any{"event_id":event,"attempts":attempt+1});break};_,_=b.DB.Exec(ctx,"UPDATE broadcast_recipients SET attempts=$1,error=$2,updated_at=NOW() WHERE id=$3",attempt+1,lastErr.Error(),x.id);select{case<-ctx.Done():return;case<-time.After(time.Duration(1<<min(attempt,5))*time.Second):}};if !sent{_,_=b.DB.Exec(ctx,"UPDATE broadcast_recipients SET status='failed',error=$1,updated_at=NOW() WHERE id=$2",errorText(lastErr),x.id);b.auditRecipient(ctx,j.CreatedBy,"broadcast.recipient.failed",j.ID,x.user,map[string]any{"error":errorText(lastErr),"attempts":x.attempts})};if j.Throttle>0{select{case<-ctx.Done():return;case<-time.After(time.Duration(j.Throttle)*time.Millisecond):}}};var pending int;_=b.DB.QueryRow(ctx,"SELECT COUNT(*) FROM broadcast_recipients WHERE broadcast_id=$1 AND status IN ('pending','retry')",j.ID).Scan(&pending);status:="completed";if pending>0{status="queued"}else{var failed int;_=b.DB.QueryRow(ctx,"SELECT COUNT(*) FROM broadcast_recipients WHERE broadcast_id=$1 AND status='failed'",j.ID).Scan(&failed);if failed>0{status="completed_with_errors"}};_,_=b.DB.Exec(ctx,"UPDATE broadcasts SET status=$1,completed_at=CASE WHEN $1='queued' THEN NULL ELSE NOW() END,updated_at=NOW() WHERE id=$2",status,j.ID)}
func(b *Broadcaster)failJob(ctx context.Context,id int64){_,_=b.DB.Exec(ctx,"UPDATE broadcasts SET status='failed',completed_at=NOW(),updated_at=NOW() WHERE id=$1",id)}
func(b *Broadcaster)auditRecipient(ctx context.Context,actor *int64,action string,broadcastID int64,userID string,payload map[string]any){if actor==nil{return};raw,err:=json.Marshal(payload);if err!=nil{return};_,err=b.DB.Exec(ctx,"INSERT INTO audit_logs(user_id,action,target_type,target_id,payload,created_at) VALUES($1,$2,'matrix_user',$3,$4,NOW())",*actor,action,userID,raw);if err!=nil{b.Logger.Warn().Err(err).Int64("broadcast_id",broadcastID).Msg("broadcast audit write failed")}}
func errorText(e error)string{if e==nil{return "unknown error"};return e.Error()}
func min(a,b int)int{if a<b{return a};return b}
